import xml.etree.ElementTree as ET

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-hitl-multi-outcome-routing/LeaveRequestBpmn/LeaveRequestBpmn.bpmn')
root = tree.getroot()

errors = []

# --- Collect all declared ids
all_ids = set()
for el in root.iter():
    eid = el.get('id')
    if eid:
        all_ids.add(eid)

# --- Check all *Ref attributes resolve
for el in root.iter():
    for attr in ('sourceRef','targetRef','attachedToRef','bpmnElement'):
        val = el.get(attr)
        if val and val not in all_ids:
            errors.append(f"Unresolved ref {attr}={val!r} on <{el.tag}>")

# --- BPMNShapes and BPMNEdges
shapes = {s.get('bpmnElement') for s in root.findall('.//bpmndi:BPMNShape', NS)}
edges  = {e.get('bpmnElement') for e in root.findall('.//bpmndi:BPMNEdge', NS)}

proc = root.find('bpmn:process', NS)
flow_nodes = []
for child in proc:
    tag = child.tag
    if tag not in (f'{{{NS["bpmn"]}}}sequenceFlow',
                   f'{{{NS["bpmn"]}}}extensionElements'):
        nid = child.get('id')
        if nid:
            flow_nodes.append((tag, nid))

seq_flows = [sf.get('id') for sf in proc.findall('bpmn:sequenceFlow', NS)]

for tag, nid in flow_nodes:
    if nid not in shapes:
        errors.append(f"Missing BPMNShape for {nid}")

for fid in seq_flows:
    if fid not in edges:
        errors.append(f"Missing BPMNEdge for {fid}")

# --- Exclusive gateway checks
for gw in proc.findall('bpmn:exclusiveGateway', NS):
    gid = gw.get('id')
    default = gw.get('default')
    outgoing = [o.text for o in gw.findall('bpmn:outgoing', NS)]
    if not default:
        errors.append(f"ExclusiveGateway {gid}: missing default attribute")
    if default and default not in outgoing:
        errors.append(f"ExclusiveGateway {gid}: default={default!r} not in outgoing {outgoing}")
    conditioned = 0
    for fid in outgoing:
        if fid == default:
            continue
        sf = proc.find(f"bpmn:sequenceFlow[@id='{fid}']", NS)
        if sf is None:
            errors.append(f"ExclusiveGateway {gid}: outgoing flow {fid} not found")
        elif sf.find('bpmn:conditionExpression', NS) is None:
            errors.append(f"ExclusiveGateway {gid}: non-default outgoing flow {fid} missing conditionExpression")
        else:
            conditioned += 1
    print(f"Gateway {gid}: default={default}, conditioned branches={conditioned}, total outgoing={len(outgoing)}")

# --- No activity/event has more than one incoming
for el in proc:
    tag = el.tag
    if 'sequenceFlow' in tag or 'extensionElements' in tag or 'exclusiveGateway' in tag:
        continue
    incoming = el.findall('bpmn:incoming', NS)
    if len(incoming) > 1:
        errors.append(f"Fake join on {el.get('id')}: {len(incoming)} incoming flows")

# --- uipath:activity type as child element check (not attribute)
for act in root.findall('.//uipath:activity', NS):
    if act.get('type'):
        errors.append(f"uipath:activity uses type= attribute instead of child uipath:type element")
    utype = act.find('uipath:type', NS)
    if utype is None:
        errors.append(f"uipath:activity missing child uipath:type")
    else:
        print(f"uipath:type value={utype.get('value')!r} (child element, correct)")

if errors:
    print("\nERRORS:")
    for e in errors:
        print(" ", e)
else:
    print("\nAll structural checks PASSED.")
EOF
